Wrap the route handlers with an authentication guard that validates the user's session or API token before proceeding.
```ts
// ~/utils/auth.ts
import { redirect } from "@react-router/server";

export async function requireAuth({ request }: { request: Request }) {
  const token = request.headers.get("Authorization")?.replace(/^Bearer\s+/i, "");
  if (!token || !(await validateToken(token))) {
    // Redirect to login or return 401
    throw redirect("/auth");
  }
  return null; // allow the route to continue
}

// In routes.ts (as shown in the previous fix) attach the loader:
route("/api/v1/chat/completions", "routes/api.v1.chat.completions.ts", { loader: requireAuth })
```
This ensures that only authenticated requests can reach the API endpoints.
